pub(crate) fn doctor_support_bundle_latest_failure_context(data_dir: &Path) -> Option<PathBuf> {
    let root = data_dir.join("doctor").join("failures");
    if !root.exists() {
        return None;
    }
    walkdir::WalkDir::new(&root)
        .follow_links(false)
        .into_iter()
        .filter_map(Result::ok)
        .filter(|entry| {
            entry.file_type().is_file()
                && entry.file_name().to_str() == Some("failure_context.json")
        })
        .filter_map(|entry| {
            let modified = entry
                .metadata()
                .ok()
                .and_then(|metadata| metadata.modified().ok());
            Some((modified?, entry.path().to_path_buf()))
        })
        .max_by_key(|(modified, _)| *modified)
        .map(|(_, path)| path)
}

